#define MAXN 20
#define MAXD 12
#define INF 0x3f3f3f3f

char grid[MAXN][MAXN];
int R, C;
int dist[MAXD+1][MAXN][MAXN]; // dist from key point i to all cells
int key_dist[MAXD+1][MAXD+1];
int dx[] = {0,0,1,-1};
int dy[] = {1,-1,0,0};

int qx[MAXN*MAXN*4], qy[MAXN*MAXN*4];

void bfs(int sx, int sy, int d[][MAXN]) {
    memset(d, 0x3f, sizeof(int)*MAXN*MAXN);
    int head=0, tail=0;
    d[sx][sy]=0;
    qx[tail]=sx; qy[tail]=sy; tail++;
    while(head<tail) {
        int x=qx[head], y=qy[head]; head++;
        for(int i=0;i<4;i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if(nx>=0&&nx<R&&ny>=0&&ny<C&&grid[nx][ny]!='x'&&d[nx][ny]==INF) {
                d[nx][ny]=d[x][y]+1;
                qx[tail]=nx; qy[tail]=ny; tail++;
            }
        }
    }
}

int dp[1<<MAXD][MAXD];

int main() {
    while(scanf("%d %d", &R, &C)==2 && (R||C)) {
        for(int i=0;i<R;i++) scanf("%s", grid[i]);

        int kx[MAXD+1], ky[MAXD+1];
        int nk=0; // dirty tiles count, index 1..nk
        int rx=-1, ry=-1;

        for(int i=0;i<R;i++) for(int j=0;j<C;j++) {
            if(grid[i][j]=='o') { rx=i; ry=j; }
            else if(grid[i][j]=='*') { kx[nk+1]=i; ky[nk+1]=j; nk++; }
        }

        if(nk==0) { printf("0\n"); continue; }

        // key point 0 = robot start
        kx[0]=rx; ky[0]=ry;

        // BFS from each key point
        for(int i=0;i<=nk;i++) {
            bfs(kx[i], ky[i], dist[i]);
        }

        // Build key_dist
        int possible=1;
        for(int i=0;i<=nk;i++) for(int j=0;j<=nk;j++) {
            key_dist[i][j]=dist[i][kx[j]][ky[j]];
            if(i!=j && key_dist[i][j]==INF) possible=0;
        }

        if(!possible) { printf("-1\n"); continue; }

        // TSP bitmask DP
        // dp[mask][i] = min moves to have cleaned dirty tiles in mask, currently at dirty tile i (1-indexed)
        int sz=1<<nk;
        memset(dp, 0x3f, sizeof(dp));
        for(int i=1;i<=nk;i++) dp[1<<(i-1)][i]=key_dist[0][i];

        for(int mask=1;mask<sz;mask++) {
            for(int i=1;i<=nk;i++) {
                if(!(mask&(1<<(i-1)))) continue;
                if(dp[mask][i]==INF) continue;
                for(int j=1;j<=nk;j++) {
                    if(mask&(1<<(j-1))) continue;
                    int nmask=mask|(1<<(j-1));
                    int nd=dp[mask][i]+key_dist[i][j];
                    if(nd<dp[nmask][j]) dp[nmask][j]=nd;
                }
            }
        }

        int ans=INF;
        int full=sz-1;
        for(int i=1;i<=nk;i++) if(dp[full][i]<ans) ans=dp[full][i];

        printf("%d\n", ans==INF?-1:ans);
    }
    return 0;
}

