    int front = 0, back = 0;

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            dist_grid[i][j] = -1;
        }
    }

    dist_grid[start.y][start.x] = 0;
    qx[back] = start.x;
    qy[back] = start.y;
    back++;

    while (front < back) {
        int x = qx[front];
        int y = qy[front];
        front++;

        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
