            if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
            if (room[ny][nx] == 'x') continue;
            if (dist_grid[ny][nx] != -1) continue;

            dist_grid[ny][nx] = dist_grid[y][x] + 1;
            qx[back] = nx;
            qy[back] = ny;
            back++;
        }
    }
}

