                    dirt_count++;
                }
            }
        }

        Point nodes[MAX_DIRT + 1];
        nodes[0] = start;
        for (int i = 0; i < dirt_count; i++) nodes[i + 1] = dirt[i];

        int n = dirt_count + 1;
        int pairdist[MAX_DIRT + 1][MAX_DIRT + 1];
        int possible = 1;

        for (int i = 0; i < n; i++) {
            bfs(nodes[i]);
            for (int j = 0; j < n; j++) {
                pairdist[i][j] = dist_grid[nodes[j].y][nodes[j].x];
            }
        }

        for (int i = 1; i < n; i++) {
            if (pairdist[0][i] == -1) {
                possible = 0;
                break;
            }
        }

        if (!possible) {
            printf("-1\n");
            continue;
        }

        if (dirt_count == 0) {
            printf("0\n");
            continue;
        }

        int dp[1 << MAX_DIRT][MAX_DIRT];
        int full = 1 << dirt_count;

        for (int m = 0; m < full; m++) {
            for (int i = 0; i < dirt_count; i++) {
                dp[m][i] = INF;
            }
        }

        for (int i = 0; i < dirt_count; i++) {
            if (pairdist[0][i + 1] != -1) {
                dp[1 << i][i] = pairdist[0][i + 1];
            }
        }

        for (int mask = 0; mask < full; mask++) {
            for (int last = 0; last < dirt_count; last++) {
                if (dp[mask][last] == INF) continue;
                for (int nxt = 0; nxt < dirt_count; nxt++) {
                    if (mask & (1 << nxt)) continue;
                    int d = pairdist[last + 1][nxt + 1];
                    if (d == -1) continue;
                    int nmask = mask | (1 << nxt);
                    if (dp[nmask][nxt] > dp[mask][last] + d) {
                        dp[nmask][nxt] = dp[mask][last] + d;
                    }
                }
            }
        }

        int ans = INF;
        for (int i = 0; i < dirt_count; i++) {
            if (dp[full - 1][i] < ans) ans = dp[full - 1][i];
        }

        if (ans == INF) ans = -1;
        printf("%d\n", ans);
    }

    return 0;
}

