                    sx = i; sy = j;
                } else if (grid[i][j] == '*') {
                    dirty.push_back({i, j});
                }
            }
        }
        int n = dirty.size();
        // Add robot start as index 0 in distance matrix
        vector<pair<int,int>> points;
        points.push_back({sx, sy});
        for (auto &p : dirty) points.push_back(p);

        // BFS from each point to get distances
        vector<vector<int>> dist(n+1, vector<int>(n+1, INF));
        for (int idx = 0; idx <= n; idx++) {
            auto [x0, y0] = points[idx];
            vector<vector<int>> d(h, vector<int>(w, INF));
            queue<pair<int,int>> q;
            d[x0][y0] = 0;
            q.push({x0, y0});
            while (!q.empty()) {
                auto [x, y] = q.front(); q.pop();
                for (int k = 0; k < 4; k++) {
                    int nx = x + dx[k], ny = y + dy[k];
                    if (nx >= 0 && nx < h && ny >= 0 && ny < w && grid[nx][ny] != 'x' && d[nx][ny] == INF) {
                        d[nx][ny] = d[x][y] + 1;
                        q.push({nx, ny});
                    }
                }
            }
            for (int j = 0; j <= n; j++) {
                auto [xj, yj] = points[j];
                dist[idx][j] = d[xj][yj];
            }
        }

        // Check unreachable
        bool possible = true;
        for (int i = 1; i <= n; i++) {
            if (dist[0][i] == INF) {
                possible = false;
                break;
            }
        }
        if (!possible) {
            cout << -1 << "\n";
            continue;
        }

        // DP over subsets
        vector<vector<int>> dp(1 << n, vector<int>(n, INF));
        for (int i = 0; i < n; i++) {
            dp[1 << i][i] = dist[0][i+1];
        }
        for (int mask = 1; mask < (1 << n); mask++) {
            for (int last = 0; last < n; last++) {
                if (!(mask & (1 << last))) continue;
                if (dp[mask][last] == INF) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if (mask & (1 << nxt)) continue;
                    int nmask = mask | (1 << nxt);
                    dp[nmask][nxt] = min(dp[nmask][nxt], dp[mask][last] + dist[last+1][nxt+1]);
                }
            }
        }
        int full = (1 << n) - 1;
        int ans = INF;
        for (int i = 0; i < n; i++) ans = min(ans, dp[full][i]);
        cout << ans << "\n";
    }
    return 0;
}

