from collections import deque

def solve():
    import sys
    input_data = sys.stdin.read().split('\n')
    idx = 0
    while idx < len(input_data) and input_data[idx].strip() == '':
        idx += 1

    results = []

    while idx < len(input_data):
        line = input_data[idx].strip()
        if not line:
            idx += 1
            continue
        parts = line.split()
        if len(parts) < 2:
            idx += 1
            continue
        rows, cols = int(parts[0]), int(parts[1])
        idx += 1
        grid = []
        for i in range(rows):
            if idx < len(input_data):
                grid.append(input_data[idx])
                idx += 1

        start = None
        dirty = []
        for r in range(rows):
            for c in range(len(grid[r])):
                ch = grid[r][c]
                if ch == '@':
                    start = (r, c)
                elif ch == '*':
                    dirty.append((r, c))

        if not dirty:
            results.append(0)
            continue

        points = [start] + dirty
        n = len(points)

        def bfs(sr, sc):
            dist = [[-1]*cols for _ in range(rows)]
            dist[sr][sc] = 0
            q = deque([(sr, sc)])
            while q:
                r, c = q.popleft()
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] == -1:
                        ch = grid[nr][nc] if nc < len(grid[nr]) else 'x'
                        if ch != 'x':
                            dist[nr][nc] = dist[r][c] + 1
                            q.append((nr, nc))
            return dist

        dists = []
        for p in points:
            dists.append(bfs(p[0], p[1]))

        # Check reachability
        adj = [[0]*n for _ in range(n)]
        possible = True
        for i in range(n):
            for j in range(n):
                r, c = points[j]
                d = dists[i][r][c]
                if d == -1:
                    if i == 0 and j > 0:
                        possible = False
                    adj[i][j] = float('inf')
                else:
                    adj[i][j] = d

        if not possible:
            results.append(-1)
            continue

        # Bitmask DP: dp[mask][i] = min moves to have cleaned dirty tiles in mask, currently at dirty tile i
        INF = float('inf')
        m = len(dirty)
        dp = [[INF]*m for _ in range(1<<m)]

        for i in range(m):
            dp[1<<i][i] = adj[0][i+1]

        for mask in range(1, 1<<m):
            for i in range(m):
                if not (mask & (1<<i)):
                    continue
                if dp[mask][i] == INF:
                    continue
                for j in range(m):
                    if mask & (1<<j):
                        continue
                    nmask = mask | (1<<j)
                    cost = dp[mask][i] + adj[i+1][j+1]
                    if cost < dp[nmask][j]:
                        dp[nmask][j] = cost

        full = (1<<m) - 1
        ans = min(dp[full])
        results.append(ans if ans != INF else -1)

    print('\n'.join(map(str, results)))

