import sys
from collections import deque

def bfs(start, grid, w, h):
    sx, sy = start
    dist = [[-1] * w for _ in range(h)]
    q = deque([(sx, sy)])
    dist[sy][sx] = 0

    while q:
        x, y = q.popleft()
        d = dist[y][x]
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < w and 0 <= ny < h and dist[ny][nx] == -1 and grid[ny][nx] != 'x':
                dist[ny][nx] = d + 1
                q.append((nx, ny))
    return dist

def solve_case(w, h, grid):
    points = []  # [robot, dirty1, dirty2, ...]
    robot = None

    for y in range(h):
        for x in range(w):
            if grid[y][x] == 'o':
                robot = (x, y)
            elif grid[y][x] == '*':
                points.append((x, y))

    if robot is None:
        return -1

    points = [robot] + points
    n = len(points) - 1  # number of dirty tiles

    if n == 0:
        return 0

    # Pairwise distances between robot/dirty tiles
    dmat = [[-1] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dist = bfs(points[i], grid, w, h)
        for j in range(n + 1):
            x, y = points[j]
            dmat[i][j] = dist[y][x]

    # If any dirty tile is unreachable from robot or between required points, impossible
    for i in range(n + 1):
        for j in range(n + 1):
            if i != j and dmat[i][j] == -1:
                # Since all points must be connected to visit all dirty tiles
                return -1

    # TSP-style DP over dirty tiles
    INF = 10**15
    size = 1 << n
    dp = [[INF] * n for _ in range(size)]

    # Start from robot to each dirty tile
    for i in range(n):
        dp[1 << i][i] = dmat[0][i + 1]

    for mask in range(size):
        for last in range(n):
            cur = dp[mask][last]
            if cur == INF:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                nmask = mask | (1 << nxt)
                nd = cur + dmat[last + 1][nxt + 1]
                if nd < dp[nmask][nxt]:
                    dp[nmask][nxt] = nd

    full = size - 1
    return min(dp[full])

