import java.util.*;

public class RobotCleaner {
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int w = sc.nextInt();
            int h = sc.nextInt();
            if (w == 0 && h == 0) break;
            sc.nextLine();
            char[][] grid = new char[h][w];
            List<int[]> points = new ArrayList<>();
            int startIdx = -1;

            for (int i = 0; i < h; i++) {
                String line = sc.nextLine();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'o') {
                        startIdx = points.size();
                        points.add(new int[]{i, j});
                    } else if (grid[i][j] == '*') {
                        points.add(new int[]{i, j});
                    }
                }
            }

            int n = points.size();
            int[][] dist = new int[n][n];
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], -1);
            }

            boolean impossible = false;
            for (int i = 0; i < n; i++) {
                int[][] bfsDist = bfs(grid, points.get(i)[0], points.get(i)[1], h, w);
                for (int j = 0; j < n; j++) {
                    dist[i][j] = bfsDist[points.get(j)[0]][points.get(j)[1]];
                    if (dist[i][j] == -1) {
                        impossible = true;
                        break;
                    }
                }
                if (impossible) break;
            }

            if (impossible) {
                System.out.println(-1);
                continue;
            }

            int totalMasks = 1 << n;
            int[][] dp = new int[totalMasks][n];
            for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);
            dp[1 << startIdx][startIdx] = 0;

            for (int mask = 0; mask < totalMasks; mask++) {
                for (int last = 0; last < n; last++) {
                    if ((mask & (1 << last)) == 0) continue;
                    for (int next = 0; next < n; next++) {
                        if ((mask & (1 << next)) != 0) continue;
                        int newMask = mask | (1 << next);
                        dp[newMask][next] = Math.min(dp[newMask][next],
                                dp[mask][last] + dist[last][next]);
                    }
                }
            }

            int fullMask = totalMasks - 1;
            int answer = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                answer = Math.min(answer, dp[fullMask][i]);
            }
            System.out.println(answer);
        }
        sc.close();
    }

    static int[][] bfs(char[][] grid, int sx, int sy, int h, int w) {
        int[][] dist = new int[h][w];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{sx, sy});
        dist[sx][sy] = 0;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx >= 0 && nx < h && ny >= 0 && ny < w && grid[nx][ny] != 'x' && dist[nx][ny] == -1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.add(new int[]{nx, ny});
                }
            }
        }
        return dist;
    }
}

import java.util.*;

public class Main {
    static int R, C;
    static char[][] grid;
    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    static int[] bfs(int sr, int sc) {
        int[] dist = new int[R * C];
        Arrays.fill(dist, -1);
        dist[sr * C + sc] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(sr * C + sc);
        while (!q.isEmpty()) {
            int cur = q.poll();
            int r = cur / C, c = cur % C;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] != 'x' && dist[nr * C + nc] == -1) {
                    dist[nr * C + nc] = dist[cur] + 1;
                    q.add(nr * C + nc);
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        R = sc.nextInt(); C = sc.nextInt();
        grid = new char[R][C];
        int startR = -1, startC = -1;
        List<int[]> dirty = new ArrayList<>();
        for (int i = 0; i < R; i++) {
            String line = sc.next();
            for (int j = 0; j < C; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'o') { startR = i; startC = j; }
                else if (grid[i][j] == 'd') dirty.add(new int[]{i, j});
            }
        }
        int n = dirty.size();
        if (n == 0) { System.out.println(0); return; }

        // key points: 0 = start, 1..n = dirty tiles
        int[][] pts = new int[n + 1][2];
        pts[0] = new int[]{startR, startC};
        for (int i = 0; i < n; i++) pts[i + 1] = dirty.get(i);

        int[][] dist = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) Arrays.fill(dist[i], Integer.MAX_VALUE / 2);

        for (int i = 0; i <= n; i++) {
            int[] d = bfs(pts[i][0], pts[i][1]);
            for (int j = 0; j <= n; j++) {
                int idx = pts[j][0] * C + pts[j][1];
                if (d[idx] != -1) dist[i][j] = d[idx];
            }
        }

        // TSP with bitmask: dp[mask][i] = min moves to have cleaned dirty tiles in mask, currently at dirty tile i
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, INF);

        for (int i = 0; i < n; i++) {
            if (dist[0][i + 1] < INF) dp[1 << i][i] = dist[0][i + 1];
        }

        for (int mask = 1; mask < (1 << n); mask++) {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0 || dp[mask][i] == INF) continue;
                for (int j = 0; j < n; j++) {
                    if ((mask & (1 << j)) != 0) continue;
                    int nmask = mask | (1 << j);
                    int nd = dp[mask][i] + dist[i + 1][j + 1];
                    if (nd < dp[nmask][j]) dp[nmask][j] = nd;
                }
            }
        }

        int full = (1 << n) - 1;
        int ans = INF;
        for (int i = 0; i < n; i++) ans = Math.min(ans, dp[full][i]);
        System.out.println(ans == INF ? -1 : ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};

    static int w, h;
    static char[][] grid;

    static int bfsDist(Point start, Point target) {
        int[][] dist = new int[h][w];
        for (int i = 0; i < h; i++) Arrays.fill(dist[i], -1);

        ArrayDeque<Point> q = new ArrayDeque<>();
        q.add(start);
        dist[start.r][start.c] = 0;

        while (!q.isEmpty()) {
            Point cur = q.poll();
            if (cur.r == target.r && cur.c == target.c) {
                return dist[cur.r][cur.c];
            }

            for (int d = 0; d < 4; d++) {
                int nr = cur.r + DR[d];
                int nc = cur.c + DC[d];
                if (nr < 0 || nr >= h || nc < 0 || nc >= w) continue;
                if (grid[nr][nc] == 'x') continue;
                if (dist[nr][nc] != -1) continue;
                dist[nr][nc] = dist[cur.r][cur.c] + 1;
                q.add(new Point(nr, nc));
            }
        }
        return -1;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();

        while (true) {
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) line = br.readLine();
            if (line == null) break;

            StringTokenizer st = new StringTokenizer(line);
            w = Integer.parseInt(st.nextToken());
            h = Integer.parseInt(st.nextToken());

            if (w == 0 && h == 0) break;

            grid = new char[h][w];
            Point start = null;
            List<Point> dirty = new ArrayList<>();

            for (int i = 0; i < h; i++) {
                String s = br.readLine();
                while (s != null && s.length() < w) s += br.readLine();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = s.charAt(j);
                    if (grid[i][j] == 'o') start = new Point(i, j);
                    else if (grid[i][j] == '*') dirty.add(new Point(i, j));
                }
            }

            int n = dirty.size();
            List<Point> points = new ArrayList<>();
            points.add(start);
            points.addAll(dirty);

            int[][] dist = new int[n + 1][n + 1];
            boolean possible = true;

            for (int i = 0; i <= n && possible; i++) {
                for (int j = i + 1; j <= n; j++) {
                    int d = bfsDist(points.get(i), points.get(j));
                    if (d == -1) {
                        possible = false;
                        break;
                    }
                    dist[i][j] = dist[j][i] = d;
                }
            }

            if (!possible) {
                out.append(-1).append('\n');
                continue;
            }

            if (n == 0) {
                out.append(0).append('\n');
                continue;
            }

            int fullMask = 1 << n;
            int INF = 1_000_000_000;
            int[][] dp = new int[fullMask][n];

            for (int i = 0; i < fullMask; i++) Arrays.fill(dp[i], INF);

            for (int i = 0; i < n; i++) {
                dp[1 << i][i] = dist[0][i + 1];
            }

            for (int mask = 0; mask < fullMask; mask++) {
                for (int last = 0; last < n; last++) {
                    if (dp[mask][last] == INF) continue;
                    for (int next = 0; next < n; next++) {
                        if ((mask & (1 << next)) != 0) continue;
                        int nextMask = mask | (1 << next);
                        dp[nextMask][next] = Math.min(dp[nextMask][next],
                                dp[mask][last] + dist[last + 1][next + 1]);
                    }
                }
            }

            int ans = INF;
            int targetMask = fullMask - 1;
            for (int last = 0; last < n; last++) {
                ans = Math.min(ans, dp[targetMask][last]);
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}
